import { readFileSync } from "node:fs";
import { join } from "node:path";
import { resolveRelative } from "../inspect/css.js";
import { addSelectedDirectives, basename, bladeArray, childrenBySig, escapeAttr, indent, parseSource, rewriteRefs, buildControlPartial, extractFieldTemplate, substituteCmsForm, substituteContactForm, } from "./blade-html.js";
import { buildImportedPage } from "./imported-page.js";
import { generateSeeder } from "./seeder.js";
import { hasSeedRows } from "./seeds.js";
import { BUILTIN_ROUTES } from "./plan.js";
import { generateImportedRoutes, generateStandalonePages, } from "./standalone.js";
/**
 * Plan に基づく変換成果物の生成（すべて決定論的。元テンプレートは read-only — spec §48）。
 * 共通 header/footer が抽出できない実案件は standalone（preserve）モードで全文書を保持する。
 */
/**
 * layout が出す og の prop（B-1）。
 *
 * **ここに在るものはページ側で出さない。** 二重に出すと、どちらが正かを
 * クローラが決めることになる。
 */
const LAYOUT_OG_PROPS = new Set([
    "og:site_name",
    "og:title",
    "og:description",
    "og:type",
    "og:url",
]);
export function generateFromPlan(sourceDir, manifest, plan, options = {}) {
    const files = [];
    const fp = manifest.fingerprint.total.slice(0, 12);
    const stamp = (source) => `{{-- generated by agentcms template apply — source: ${source} (fingerprint ${fp}) — 手動編集すると再 apply 時に conflict になります --}}\n`;
    const contactConstants = plan.cms_integrations
        .filter((i) => i.id === "contact-form")
        .flatMap((i) => i.server_constants ?? []);
    // ---- standalone（preserve）モード ----
    if (plan.layout.header_selector === null) {
        // assets / media は共通処理
        pushAssetFiles(files, sourceDir, plan);
        const standalone = generateStandalonePages(sourceDir, manifest, plan);
        files.push(...standalone.files);
        if (hasSeedRows(plan)) {
            files.push({
                target: "database/seeders/TemplateContentSeeder.php",
                content: generateSeeder(plan),
                source: "manifest repeats（カード / ニュース抽出データ）",
            });
        }
        /*
         * ---- 画面から編集できるページ（R03 / B-42）----
         *
         * standalone の各ページ（`resources/views/public/*`、URL が決まっているもの）を
         * ページの材料にする。トップは `front_page_id` で `/` に出る（R-5）。
         * 他のページは `routes/imported.php` が `ImportedPageController` を通し、
         * **結び付いたページが公開されていればそれ、無ければ静的な Blade** を出す。
         *
         * ▷ 生成した静的な Blade は**そのまま残す**。ページが無い・未公開のときの受け皿。
         */
        const editable = buildEditablePages(files, plan, options);
        files.push(...editable.files);
        return {
            files,
            schemaPatches: plan.schema_changes
                .filter((c) => c.change === "add_choices" && c.confidence === "CONFIDENT")
                .map((c) => ({ schema: c.schema, field: c.field, values: c.values })),
            envAdditions: plan.env_additions,
            contactConstants,
            importedPages: editable.pages,
            importedPageNotes: editable.notes,
        };
    }
    // ---- assets（構造を保持してコピー） ----
    pushAssetFiles(files, sourceDir, plan);
    // ---- shared components（cta 等） ----
    const componentIncludes = new Map(); // selector -> @include 行
    for (const comp of plan.components) {
        const page = comp.source_pages[0];
        if (!page)
            continue;
        const root = parseSource(sourceDir, page);
        const el = root.querySelector(comp.source_pattern.replace(/^section\./, "section."));
        if (!el)
            continue;
        rewriteRefs(el, page, plan);
        const viewName = comp.target_blade
            .replace(/^resources\/views\//, "")
            .replace(/\.blade\.php$/, "")
            .replaceAll("/", ".");
        componentIncludes.set(comp.source_pattern, `@include('${viewName}')`);
        files.push({
            target: comp.target_blade,
            content: `${stamp(`${page} ${comp.source_pattern}`)}${el.outerHTML.trim()}\n`,
            source: `${page} ${comp.source_pattern}`,
        });
    }
    // ---- layout ----
    const referencePage = plan.pages.find((p) => p.source === "index.html") ?? plan.pages[0];
    if (!referencePage)
        throw new Error("plan に pages がありません");
    const layoutResult = generateLayout(sourceDir, manifest, plan, referencePage.source);
    files.push({
        target: plan.layout.target,
        content: `${stamp(`${referencePage.source} (${plan.layout.header_selector} / ${plan.layout.footer_selector})`)}${layoutResult.content}`,
        source: referencePage.source,
    });
    // ---- pages ----
    for (const pagePlan of plan.pages) {
        if (pagePlan.route === null)
            continue; // 未対応ページは生成しない（plan で REVIEW 済み）
        files.push({
            target: pagePlan.target,
            content: stamp(pagePlan.source) +
                generatePage(sourceDir, manifest, plan, pagePlan.source, {
                    layoutCommon: layoutResult.common,
                    componentIncludes,
                }),
            source: pagePlan.source,
        });
    }
    /*
     * ---- 取り込んだ意匠の CMS フォーム（R-12 Stage 2 / D）----
     *
     * 同じ原本から**もう 1 通り**書き出す。旧 Contact パイプラインへ繋いだものは
     * `modules/Contact/views/form.blade.php` のまま残し、こちらは **CMS のフォーム**を
     * 取り込んだ意匠で描く。`ContactEntry` は**この view が在るかどうか**で
     * 切り替えを決めるので、**書けた案件だけが切り替わる**。
     *
     * ▷ **両方書く。** 片方だけにすると、切り替えを戻したいときに戻す先が無い。
     *   旧側は Stage 3 で module ごと消える（R-12 裁定 1）。
     */
    const contactPage = plan.pages.find((p) => plan.cms_integrations.some((i) => i.id === "contact-form" && i.regions.some((r) => r.page === p.source)));
    if (contactPage !== undefined) {
        const partial = "forms.partials.imported-control";
        const cmsFormPage = generatePage(sourceDir, manifest, plan, contactPage.source, { layoutCommon: layoutResult.common, componentIncludes, cmsForm: { partial } });
        files.push({
            target: "resources/views/forms/imported.blade.php",
            content: stamp(contactPage.source) + cmsFormPage,
            source: contactPage.source,
        });
        const template = extractFieldTemplate(parseSource(sourceDir, contactPage.source).querySelector(plan.cms_integrations
            .find((i) => i.id === "contact-form")
            .regions.find((r) => r.page === contactPage.source).container));
        if (template !== null) {
            files.push({
                target: "resources/views/forms/partials/imported-control.blade.php",
                content: buildControlPartial(template),
                source: contactPage.source,
            });
        }
    }
    /*
     * ---- 標準規約外ページの route（監査 指摘 33）----
     *
     * これまで **standalone モードだけ**が `routes/imported.php` を生成していた。
     * layout モードは汎用ページの view（`resources/views/pages/<name>.blade.php`）を
     * **書くのに route を登録していなかった**ので、生成した Blade の `route('works')` が
     * どこにも当たらず例外になる。
     *
     * ▷ 受け皿の型が無いページは、R-13 で**汎用ページへ落とす**ようにした。
     *   落とし先に route が無ければ、**落としただけで壊れる**。
     */
    const importedRoutePages = plan.pages.filter((p) => p.route !== null && !BUILTIN_ROUTES.has(p.route));
    if (importedRoutePages.length > 0) {
        files.push({
            target: "routes/imported.php",
            content: generateImportedRoutes(importedRoutePages, fp),
            source: "標準規約外ページ（汎用 route）",
        });
    }
    // ---- seeder ----
    if (hasSeedRows(plan)) {
        files.push({
            target: "database/seeders/TemplateContentSeeder.php",
            content: generateSeeder(plan),
            source: "manifest repeats（カード / ニュース抽出データ）",
        });
    }
    return {
        files,
        // REVIEW の schema 変更提案（project override 等）は自動適用しない — 人間承認後に別途反映
        schemaPatches: plan.schema_changes
            .filter((c) => c.change === "add_choices" && c.confidence === "CONFIDENT")
            .map((c) => ({ schema: c.schema, field: c.field, values: c.values })),
        envAdditions: plan.env_additions,
        contactConstants,
        /*
         * layout モードは対象外（この版）。header / footer を抽出できた案件は
         * `layouts.imported` に載る別の道で、`layouts.preserved` の 2 本立て（B-38）とは
         * 枠の作り方が違う。**無いことを黙らない** — 理由を残す。
         */
        importedPages: [],
        importedPageNotes: [
            "layout モード（共通 header / footer を抽出した案件）では、この版はページを起こしません",
        ],
    };
}
/**
 * standalone モードの各ページを、編集できるページの材料にする（R03 続き (1)）。
 *
 * 元にするのは**生成済みの Blade**（`files` の中の `resources/views/public/*.blade.php`）。
 * 原本から起こすと `asset()` 化の前の参照を持ち込んで画像が壊れる。
 *
 * 対象は `resources/views/public/`・`resources/views/pages/` に書き出した、URL が決まっていて `{slug}` を含まないページ。
 * module の view（`modules/Works/views/index.blade.php` 等 — CMS の一覧）は対象にしない。
 * トップ（`/`）だけが `front`。他のページは `agentcms:import-page` が作るページの結び付き
 * （`imported_page_layouts`）を `ImportedPageController` が見て、**元の URL でそのページを出す**
 * （`routes/imported.php` の `Route::view` を置き換えた。静的な Blade は結び付きが無いときの受け皿）。
 */
function buildEditablePages(files, plan, options) {
    const out = { files: [], pages: [], notes: [] };
    const knownTypes = options.knownTypes ??
        new Set([
            ...plan.cms_integrations.map((i) => i.schema),
            ...plan.content_types.map((t) => t.id),
        ]);
    const done = new Set();
    // トップを先に（`front_page_id` はトップの結果で決まる。表示・記録の順も原本の入口から）
    const ordered = [...plan.pages].sort((a, b) => a.url === "/" ? -1 : b.url === "/" ? 1 : (a.url ?? "").localeCompare(b.url ?? ""));
    for (const page of ordered) {
        if (page.url === null || page.url.includes("{slug}"))
            continue;
        // 標準ページ（public/）と規約外の汎用ページ（pages/）。module の view は CMS の一覧なので対象外
        if (!page.target.startsWith("resources/views/public/") &&
            !page.target.startsWith("resources/views/pages/"))
            continue;
        if (done.has(page.target))
            continue;
        done.add(page.target);
        const generated = files.find((f) => f.target === page.target);
        if (generated === undefined) {
            out.notes.push(`${page.source}: 生成した Blade が見つからないため、ページは作りません`);
            continue;
        }
        const slug = importedPageSlug(page.url);
        if (slug === null) {
            out.notes.push(`${page.source}: URL [${page.url}] からページの slug を決められないため作りません`);
            continue;
        }
        const built = buildImportedPage({
            source: page.source,
            blade: generated.content.toString(),
            title: page.title ?? (slug === "home" ? "ホーム" : slug),
            slug,
            scope: slug,
            publish: true,
            front: page.url === "/",
            knownTypes,
            routeUrls: new Map(plan.pages.flatMap((p) => p.route !== null && p.url !== null && !p.url.includes("{") ? [[p.route, p.url]] : [])),
        });
        if (typeof built === "string") {
            out.notes.push(built);
            continue;
        }
        out.files.push(...built.files);
        out.pages.push(built.page);
    }
    return out;
}
/**
 * URL からページの slug を決める（`/` → `home`、`/about` → `about`、`/a/b` → `a-b`）。
 * `CreatePage` の slug 規則（`[a-z0-9]+(-[a-z0-9]+)*`）に収まらなければ null。
 */
export function importedPageSlug(url) {
    if (url === "/")
        return "home";
    const slug = url
        .replace(/^\/+|\/+$/g, "")
        .toLowerCase()
        .replaceAll(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
    return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug) ? slug : null;
}
/** 静的 asset の copy と Media 候補の seeder 用取り込み（両モード共通） */
function pushAssetFiles(files, sourceDir, plan) {
    for (const asset of plan.assets.static) {
        files.push({
            target: asset.to,
            content: readFileSync(join(sourceDir, asset.from)),
            source: asset.from,
        });
    }
    // Media 候補は seeder が取り込む（public へは置かない）
    for (const media of plan.assets.media) {
        files.push({
            target: `database/seeders/template-import/${basename(media.from)}`,
            content: readFileSync(join(sourceDir, media.from)),
            source: media.from,
        });
    }
}
function generateLayout(sourceDir, manifest, plan, referenceSource) {
    const root = parseSource(sourceDir, referenceSource);
    const pages = manifest.pages;
    const onAllPages = (kinds) => new Set(manifest.external
        .filter((e) => kinds.includes(e.kind) && e.pages.length === pages.length)
        .map((e) => e.url));
    // preconnect は元テンプレートで stylesheet より前に置かれている最適化。
    // layout 統合で stack（stylesheet の後）に落ちると無効になるため、全ページ分を先頭へ巻き上げる
    const preconnectTags = new Map();
    for (const pagePlan of plan.pages) {
        const pageRoot = parseSource(sourceDir, pagePlan.source);
        for (const el of pageRoot.querySelectorAll('link[rel="preconnect"]')) {
            const href = el.getAttribute("href") ?? "";
            if (/^(https?:)?\/\//.test(href) && !preconnectTags.has(href))
                preconnectTags.set(href, el.outerHTML);
        }
    }
    const common = {
        headExternal: onAllPages(["style", "font"]),
        externalJs: onAllPages(["script"]),
        preconnects: new Set(preconnectTags.keys()),
        localCss: new Set(manifest.assets.css.filter((c) => pages.every((p) => p.css.includes(c)))),
        localJs: new Set(manifest.assets.js.filter((j) => pages.every((p) => p.js.includes(j)))),
    };
    const header = plan.layout.header_selector
        ? root.querySelector(plan.layout.header_selector)
        : null;
    const footer = plan.layout.footer_selector
        ? root.querySelector(plan.layout.footer_selector)
        : null;
    if (header)
        rewriteRefs(header, referenceSource, plan);
    if (footer)
        rewriteRefs(footer, referenceSource, plan);
    const lang = pages.find((p) => p.path === referenceSource)?.head.lang ?? "ja";
    const externalHeadLinks = [...common.headExternal]
        .sort()
        .map((url) => headLinkFor(root, url))
        .filter(Boolean);
    const cssLinks = [...common.localCss]
        .sort()
        .map((c) => `    <link rel="stylesheet" href="{{ asset('${plan.assets.target_prefix}/${c}') }}">`);
    const jsTags = [
        ...[...common.externalJs].sort().map((url) => {
            const el = root
                .querySelectorAll("script[src]")
                .find((s) => s.getAttribute("src") === url);
            return `    ${el?.outerHTML ?? `<script src="${url}"></script>`}`;
        }),
        ...[...common.localJs]
            .sort()
            .map((j) => `    <script src="{{ asset('${plan.assets.target_prefix}/${j}') }}"></script>`),
    ];
    return {
        common,
        content: `<!DOCTYPE html>
<html lang="${lang}">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>{{ $title }}</title>
    @if (!empty($metaDescription))
        <meta name="description" content="{{ $metaDescription }}">
    @endif

    {{-- SEO 標準セット。**ページごとに書かない** —
         新しいページを足した人が忘れるし、忘れたことに誰も気づかない。
         原本が同じ prop を持っていた場合は、ページ側では出さない（二重に出さない） --}}
    <link rel="canonical" href="{{ url()->current() }}">
    <meta property="og:site_name" content="{{ $site['site_name'] ?? config('app.name') }}">
    <meta property="og:title" content="{{ $title }}">
    {{-- 「??」ではなく「?:」— **空文字は「未設定」として扱う**。
         「??」だと空文字がそのまま通り、og:description が空で出る --}}
    <meta property="og:description" content="{{ $metaDescription ?: ($site['seo_description'] ?? '') }}">
    <meta property="og:type" content="{{ $ogType ?? 'website' }}">
    <meta property="og:url" content="{{ url()->current() }}">
${[...preconnectTags.values()].map((tag) => `    ${tag}`).join("\n")}
${externalHeadLinks.join("\n")}
${cssLinks.join("\n")}
    @stack('head')
</head>
<body>
${indent(header?.outerHTML.trim() ?? "", 4)}

    <main>
        @yield('content')
    </main>

${indent(footer?.outerHTML.trim() ?? "", 4)}

${jsTags.join("\n")}
    @stack('scripts')
</body>
</html>
`,
    };
}
/** 参照ページの元 <link> タグを再現する（rel/attrs 保持） */
function headLinkFor(root, url) {
    const el = root
        .querySelectorAll("link[href]")
        .find((l) => l.getAttribute("href") === url);
    if (el)
        return `    ${el.outerHTML}`;
    return `    <link rel="stylesheet" href="${url}">`;
}
function generatePage(sourceDir, manifest, plan, pageSource, ctx) {
    const root = parseSource(sourceDir, pageSource);
    const pageEntry = manifest.pages.find((p) => p.path === pageSource);
    const main = root.querySelector("main");
    if (!main)
        throw new Error(`${pageSource}: <main> が見つかりません`);
    // 共通コンポーネント領域 → @include へ置換
    for (const [selector, include] of ctx.componentIncludes) {
        const el = main.querySelector(selector);
        if (el)
            el.replaceWith(`\n${include}\n`);
    }
    // CMS 統合
    const integrations = plan.cms_integrations.filter((i) => i.regions.some((r) => r.page === pageSource));
    for (const integration of integrations) {
        const region = integration.regions.find((r) => r.page === pageSource);
        if (integration.id === "works-cards") {
            substituteWorks(main, region.container, region.item ?? "", pagePlanOf(plan, pageSource));
        }
        else if (integration.id === "news-list") {
            substituteNews(main, region.container, region.item ?? "", integration.detail_route ?? null, integration.schema);
        }
        else if (integration.id === "contact-form") {
            if (ctx.cmsForm !== undefined) {
                const template = extractFieldTemplate(main.querySelector(region.container));
                if (template !== null) {
                    substituteCmsForm(main, region.container, template, ctx.cmsForm.partial);
                }
            }
            else {
                substituteContactForm(main, region.container, integration.field_mapping);
            }
        }
    }
    rewriteRefs(main, pageSource, plan);
    // head: ページ固有の push（canonical / OGP / preconnect / ページ固有 script）
    const headPush = [];
    if (pageEntry) {
        /*
         * **canonical と標準 og は layout が出す。** ここでは出さない。
         *
         * 原本が持っていたページだけが持つ形にすると、**取り込んだ時点で不揃い**になる
         * （見本は 5 ページ中 1 枚しか持っていなかった）。共通のものは共通の場所に 1 回だけ。
         * 同じ prop をここでも出すと、**1 ページに `og:title` が 2 つ**並ぶ。
         */
        for (const [prop, value] of Object.entries(pageEntry.head.og)) {
            if (LAYOUT_OG_PROPS.has(prop))
                continue;
            headPush.push(`<meta property="${prop}" content="${escapeAttr(value)}">`);
        }
        if (pageEntry.head.robots) {
            headPush.push(`<meta name="robots" content="${escapeAttr(pageEntry.head.robots)}">`);
        }
        // 全ページ共通でない外部 head リンク（preconnect 等）
        for (const el of root.querySelectorAll('link[rel="preconnect"], link[rel="stylesheet"], link[rel="preload"]')) {
            const href = el.getAttribute("href") ?? "";
            if (/^(https?:)?\/\//.test(href) &&
                !ctx.layoutCommon.headExternal.has(href) &&
                !ctx.layoutCommon.preconnects.has(href)) {
                headPush.push(el.outerHTML);
            }
        }
    }
    if (integrations.some((i) => i.id === "contact-form")) {
        headPush.push('<script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script>');
    }
    // ページ固有の script（layout 共通でない外部 / ローカル script）
    const scriptPush = [];
    for (const el of root.querySelectorAll("script[src]")) {
        const src = el.getAttribute("src") ?? "";
        if (/^(https?:)?\/\//.test(src)) {
            if (!ctx.layoutCommon.externalJs.has(src))
                scriptPush.push(el.outerHTML);
        }
        else {
            const resolved = resolveRelative(pageSource, src) ?? src;
            if (!ctx.layoutCommon.localJs.has(resolved)) {
                scriptPush.push(`<script src="{{ asset('${plan.assets.target_prefix}/${resolved}') }}"></script>`);
            }
        }
    }
    const title = pageEntry?.title ?? pageSource;
    const description = pageEntry?.head.description;
    const parts = [];
    parts.push(`@extends('${plan.layout.target
        .replace(/^resources\/views\//, "")
        .replace(/\.blade\.php$/, "")
        .replaceAll("/", ".")}', ${bladeArray({ title, metaDescription: description ?? null })})`);
    if (headPush.length > 0) {
        parts.push("", "@push('head')", ...headPush.map((l) => `    ${l}`), "@endpush");
    }
    if (scriptPush.length > 0) {
        parts.push("", "@push('scripts')", ...scriptPush.map((l) => `    ${l}`), "@endpush");
    }
    parts.push("", "@section('content')", main.innerHTML.trim(), "@endsection", "");
    let content = parts.join("\n");
    // select の old() 復元は closing タグ内が対象のため文字列パスで付与する
    content = addSelectedDirectives(content);
    return content;
}
function pagePlanOf(plan, source) {
    const page = plan.pages.find((p) => p.source === source);
    return page?.target.startsWith("modules/Works") ? "$items" : "$works";
}
/** works カード繰り返し → @foreach（1 件目のカードをテンプレート化） */
function substituteWorks(main, containerSelector, itemSig, listVar) {
    const container = main.querySelector(containerSelector);
    if (!container)
        return;
    const first = childrenBySig(container, itemSig)[0];
    if (!first)
        return;
    const heading = first.querySelector("h1, h2, h3, h4, h5, h6");
    if (heading)
        heading.set_content("{{ $work->title }}");
    const img = first.querySelector("img[src]");
    if (img) {
        img.setAttribute("src", "{{ $work->mainImage?->url() }}");
        img.setAttribute("alt", "{{ $work->mainImage?->alt ?? '' }}");
    }
    const meta = first
        .querySelectorAll("*")
        .find((c) => /(^|[\s-])meta([\s-]|$)/.test(c.getAttribute("class") ?? ""));
    if (meta)
        meta.set_content("{{ $work->category }} / {{ $work->completed_at?->format('Y') }}");
    container.set_content(`\n@foreach (${listVar} as $work)\n${indent(first.outerHTML.trim(), 2)}\n@endforeach\n`);
}
/** news リスト繰り返し → @foreach（1 件目をテンプレート化。href="#" は実リンクへ） */
function substituteNews(main, containerSelector, itemSig, detailRoute, schemaId) {
    const container = main.querySelector(containerSelector);
    if (!container)
        return;
    const first = childrenBySig(container, itemSig)[0];
    if (!first)
        return;
    const time = first.querySelector("time");
    if (time) {
        time.setAttribute("datetime", "{{ $item->published_at?->format('Y-m-d') }}");
        time.set_content("{{ $item->published_at?->format('Y.m.d') }}");
    }
    const link = first.querySelector("a[href]");
    if (link) {
        /*
         * **名前付き route が無い型もある**（R-13 Stage 2）。
         * CMS が持つ投稿タイプの公開面は `Route::fallback` が受けるので、
         * `route()` ではなく素の URL（`/<type>/<slug>`）を書く。
         */
        link.setAttribute("href", detailRoute === null
            ? `/${schemaId}/{{ $item->slug }}`
            : `{{ route('${detailRoute}', $item->slug) }}`);
        link.set_content("{{ $item->title }}");
    }
    container.set_content(`\n@foreach ($news as $item)\n${indent(first.outerHTML.trim(), 2)}\n@endforeach\n`);
}
